import { useRef } from "react";
import { ClickSpark } from "solen-design/react";

export default function App() {
  const sparkRef = useRef(null);
  return (
    <ClickSpark
      ref={sparkRef}
      shape="streak"
      sparkColor={["#ffffff", "#fbbf24", "#f472b6"]}
      sparkRadius={34}
      sparkCount={10}
      glow={0.5}
      ring={true}
    >
      <button onClick={() => sparkRef.current?.spark()}>点我溅射</button>
    </ClickSpark>
  );
}
